import { CURRENT_SCHEME_ID, SCHEME_ID_LENGTH, SCHEMES } from './schemes';
import type { WasmHashContext } from './types';

export type { WasmHashContext } from './types';

/** Query parameter that carries the hash on WASM join links. */
export const WASM_HASH_PARAM = 'wasmJoinId';

/** Creates a versioned hash of the context. */
export const createWasmHash = async (ctx: WasmHashContext): Promise<string> => {
  const scheme = SCHEMES.get(CURRENT_SCHEME_ID);
  if (!scheme) {
    throw new Error(`No scheme registered for CURRENT_SCHEME_ID ${CURRENT_SCHEME_ID}`);
  }
  return `${CURRENT_SCHEME_ID}${await scheme.create(ctx)}`;
};

/** Returns true if `value` matches an accepted scheme's hash of the context. */
export const verifyWasmHash = async (value: string, ctx: WasmHashContext): Promise<boolean> => {
  const scheme = SCHEMES.get(value.slice(0, SCHEME_ID_LENGTH));
  if (!scheme) {
    return false;
  }
  return scheme.verify(value.slice(SCHEME_ID_LENGTH), ctx);
};
